<script setup lang="ts">
import { ref } from 'vue'; import { useForm } from '@inertiajs/vue3'; import { displayDate } from '../../labels';
export interface HostNotice { id: string; type: 'arrivee'|'non_liste'|'hors_periode'; message: string; full_name: string; organisation: string | null; agent: string | null; created_at: string; read_at: string | null; decision: string | null; decided_at: string | null }
const props=defineProps<{ notice: HostNotice }>();const form=useForm({accepted:true,reason:''});const read=useForm({});const declining=ref(false);
function decide(accepted:boolean){form.accepted=accepted;form.post('/hote/notifications/'+props.notice.id+'/decision');}
</script>
<template><article class="space-y-4 rounded-2xl border-2 bg-white p-5" :class="notice.read_at?'border-slate-300':'border-ikoma-blue'" :data-testid="'notification-'+notice.type"><h2 class="break-words text-heading font-bold">{{ notice.full_name }}</h2><p v-if="notice.organisation" class="break-words">{{ notice.organisation }}</p><p class="font-semibold">{{ notice.read_at?'✓ Lue':'● Non lue' }} · {{ notice.message }}</p><p>{{ displayDate(notice.created_at) }}<span v-if="notice.agent"> · Agent : {{ notice.agent }}</span></p><p v-if="notice.decided_at" role="status" class="font-bold">{{ notice.decision==='autorise'?'✓ Vous avez accepté.':'✕ Vous avez refusé.' }}</p><template v-else-if="notice.type!=='arrivee'"><p v-if="notice.type==='non_liste'">En cas d’accord : zone d’accueil uniquement, avec accompagnement.</p><div v-if="!declining" class="grid gap-3"><button class="btn-ok" :disabled="form.processing" @click="decide(true)">✓ {{ notice.type==='hors_periode'?'Autorisé':'J’accepte' }}</button><button class="btn-no" :disabled="form.processing" @click="declining=true">✕ {{ notice.type==='hors_periode'?'Non autorisé':'Je refuse' }}</button></div><form v-else class="space-y-4" @submit.prevent="decide(false)"><label class="block">Motif du refus (facultatif)<textarea v-model="form.reason" class="field" maxlength="500" /></label><button class="btn-no" :disabled="form.processing" type="submit">Confirmer le refus</button><button class="btn-soft" type="button" @click="declining=false">Annuler</button></form></template><button v-if="!notice.read_at" class="btn-soft" :disabled="read.processing" @click="read.post('/hote/notifications/'+notice.id+'/lue')">Marquer comme lue</button><p v-for="(error,key) in form.errors" :key="key" role="alert">{{ error }}</p></article></template>
